are any, check the sku conflict, then create.

The order matters. A request with a blank name *and* a duplicate sku should get
the 400 — you can see the blank name without touching the database.

## Hint 2

Build a `Dictionary<string, string[]>` and add an entry per broken field, keyed
exactly `"name"`, `"sku"` and `"priceCents"`. Do not return early on the first
one; the gate checks that all three keys are present when all three are wrong.

`TypedResults.ValidationProblem(errors)` turns that dictionary into a 400 with
`application/problem+json` and the `errors` object.

For the conflict, `await db.Widgets.AnyAsync(w => w.Sku == request.Sku)` and
`TypedResults.Problem(title:, detail:, statusCode: StatusCodes.Status409Conflict)`.

## Hint 3

```csharp
var errors = new Dictionary<string, string[]>();

if (string.IsNullOrWhiteSpace(request.Name))
{
    errors["name"] = ["Name is required."];
}
// … sku, priceCents …

if (errors.Count > 0)
{
    return TypedResults.ValidationProblem(errors);
}
```

Then the sku check, then build the `Widget`, `Add`, `SaveChangesAsync`, and
return `TypedResults.Created($"/l07/widgets/{widget.Id}", new WidgetDto(...))`.

Note the body is a **DTO**, not the entity you just saved — the leak rule from
ex1 applies to writes as well as reads.

references.Ex2.cs:
// 07_rest_crud / ex2 - reference solution (author only, used by `dojo verify`).

using Microsoft.EntityFrameworkCore;

namespace DotnetDojo.Api.L07_RestCrud;

public class Ex2 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPost("/l07/widgets", Create);
    }

    private static async Task<IResult> Create(CreateWidget request, WidgetDb db)
    {
        var errors = new Dictionary<string, string[]>();

        if (string.IsNullOrWhiteSpace(request.Name))
        {
            errors["name"] = ["Name is required."];
        }

        if (string.IsNullOrWhiteSpace(request.Sku))
        {
            errors["sku"] = ["Sku is required."];
        }

        if (request.PriceCents <= 0)
        {
            errors["priceCents"] = ["PriceCents must be greater than zero."];
        }

        if (errors.Count > 0)
        {
            return TypedResults.ValidationProblem(errors);
        }

        if (await db.Widgets.AnyAsync(w => w.Sku == request.Sku))
        {
            return TypedResults.Problem(
                title: "Duplicate sku",
                detail: $"A widget with sku '{request.Sku}' already exists.",
                statusCode: StatusCodes.Status409Conflict);
        }

        var widget = new Widget
        {
            Name = request.Name!,
            Sku = request.Sku!,
            PriceCents = request.PriceCents,
        };

        db.Widgets.Add(widget);
        await db.SaveChangesAsync();

        return TypedResults.Created(
            $"/l07/widgets/{widget.Id}",
            new WidgetDto(widget.Id, widget.Name, widget.Sku, widget.PriceCents));
    }
}

references.Ex3.cs:
// 07_rest_crud / ex3 - reference solution (author only, used by `dojo verify`).

namespace DotnetDojo.Api.L07_RestCrud;

public class Ex3 : IEndpointMapper
{
    public void MapEndpoints(IEndpointRouteBuilder app)
    {
        app.MapPut("/l07/widgets/{id:int}", ReplaceWidget);
    }

    private static async Task<IResult> ReplaceWidget(int id, UpdateWidget request, WidgetDb db)
    {
        var widget = await db.Widgets.FindAsync(id);
        if (widget is null)
        {
            return TypedResults.NotFound();
        }

        var errors = new Dictionary<string, string[]>();

        if (string.IsNullOrWhiteSpace(request.Name))
        {
            errors["name"] = ["Name is required."];
        }

        if (string.IsNullOrWhiteSpace(request.Sku))
        {
            errors["sku"] = ["Sku is required."];
        }

        if (request.PriceCents <= 0)
        {
            errors["priceCents"] = ["PriceCents must be greater than zero."];
        }

        if (errors.Count > 0)
        {
            return TypedResults.ValidationProblem(errors);
        }

        widget.Name = request.Name!;
        widget.Sku = request.Sku!;
        widget.PriceCents = request.PriceCents;

        await db.SaveChangesAsync();

        return TypedResults.NoContent();
    }
}

