                f.Screenings
                    .OrderBy(s => s.Day).ThenBy(s => s.Id)
                    .Select(s => (int?)s.Day)
                    .FirstOrDefault(),
                f.Screenings
                    .OrderBy(s => s.Day).ThenBy(s => s.Id)
                    .Select(s => (string?)s.Room)
                    .FirstOrDefault()))
            .ToListAsync();

        return TypedResults.Ok(rows);
    }
}

