    {
        if (string.IsNullOrWhiteSpace(request.Name))
        {
            return TypedResults.BadRequest();
        }

        int count = basket.Add(request.Name);
        return TypedResults.Created(
            $"/i1/review/basket/items/{count}",
            new BasketResponse(basket.Id, count));
    }
}

